//   - Data forwarding for hazard resolution
//   - Branch prediction with flush
//   - 32 x 32-bit register file
//==============================================================================

module riscv_cpu (
    input  wire        clk,
    input  wire        rst_n,

    // Instruction Memory Interface
    output wire [31:0] imem_addr,
    input  wire [31:0] imem_data,

    // Data Memory Interface
    output wire [31:0] dmem_addr,
    output wire [31:0] dmem_wdata,
    output wire        dmem_wen,
    output wire [3:0]  dmem_be,
    input  wire [31:0] dmem_rdata,

    // Debug Interface
    output wire [31:0] debug_pc,
    output wire [31:0] debug_inst
);

    // ---------------- ALU operation encodings ----------------
    localparam [2:0] ALU_ADD = 3'b000;
    localparam [2:0] ALU_SUB = 3'b001;
    localparam [2:0] ALU_AND = 3'b010;
    localparam [2:0] ALU_OR  = 3'b011;
    localparam [2:0] ALU_XOR = 3'b100;
    localparam [2:0] ALU_SLT = 3'b101;
    localparam [2:0] ALU_SLL = 3'b110;
    localparam [2:0] ALU_SRL = 3'b111;

    // ---------------- PC ----------------
    reg  [31:0] pc;
    wire [31:0] pc_plus4 = pc + 32'd4;

    assign imem_addr  = pc;
    assign debug_pc   = pc;
    assign debug_inst = ifid_inst;

    // ---------------- IF/ID pipeline register ----------------
    reg [31:0] ifid_pc;
    reg [31:0] ifid_inst;

    // ---------------- ID/EX pipeline register ----------------
    reg [31:0] idex_pc;
    reg [31:0] idex_rs1_data;
    reg [31:0] idex_rs2_data;
    reg [4:0]  idex_rs1;
    reg [4:0]  idex_rs2;
    reg [4:0]  idex_rd;
    reg [31:0] idex_imm;
    reg        idex_regwrite;
    reg        idex_memread;
    reg        idex_memwrite;
    reg        idex_alusrc;
    reg        idex_branch;
    reg        idex_jump;
    reg        idex_is_jalr;
    reg [2:0]  idex_alu_op;
    reg [2:0]  idex_funct3;

    // ---------------- EX/MEM pipeline register ----------------
    reg [31:0] exmem_alu_result;
    reg [31:0] exmem_mem_data;
    reg [4:0]  exmem_rd;
    reg        exmem_regwrite;
    reg        exmem_memread;
    reg        exmem_memwrite;

    // ---------------- MEM/WB pipeline register ----------------
    reg [31:0] memwb_mem_data;
    reg [31:0] memwb_alu_result;
    reg [4:0]  memwb_rd;
    reg        memwb_regwrite;
    reg        memwb_memread;

    // ---------------- Register file ----------------
    reg [31:0] regfile [0:31];
    integer i;
    initial begin
        for (i = 0; i < 32; i = i + 1)
            regfile[i] = 32'd0;
    end

    // ---------------- ID stage fields ----------------
    wire [6:0] opcode    = ifid_inst[6:0];
    wire [4:0] rs1_id    = ifid_inst[19:15];
    wire [4:0] rs2_id    = ifid_inst[24:20];
    wire [4:0] rd_id     = ifid_inst[11:7];
    wire [2:0] funct3_id = ifid_inst[14:12];
    wire [6:0] funct7_id = ifid_inst[31:25];

    wire [31:0] rs1_data_id = (rs1_id == 5'd0) ? 32'd0 : regfile[rs1_id];
    wire [31:0] rs2_data_id = (rs2_id == 5'd0) ? 32'd0 : regfile[rs2_id];

    // Immediate generation
    wire [31:0] imm_i = {{20{ifid_inst[31]}}, ifid_inst[31:20]};
    wire [31:0] imm_s = {{20{ifid_inst[31]}}, ifid_inst[31:25], ifid_inst[11:7]};
    wire [31:0] imm_b = {{19{ifid_inst[31]}}, ifid_inst[31], ifid_inst[7],
                         ifid_inst[30:25], ifid_inst[11:8], 1'b0};
    wire [31:0] imm_j = {{11{ifid_inst[31]}}, ifid_inst[31], ifid_inst[19:12],
                         ifid_inst[20], ifid_inst[30:21], 1'b0};

    // ---------------- Decode / Control ----------------
    reg [31:0] imm_out;
    reg        ctrl_regwrite;
    reg        ctrl_memread;
    reg        ctrl_memwrite;
    reg        ctrl_alusrc;
    reg        ctrl_branch;
    reg        ctrl_jump;
    reg        ctrl_is_jalr;
    reg [2:0]  ctrl_alu_op;
    reg memwb_result;

    always @(*) begin
        imm_out       = 32'd0;
        ctrl_regwrite = 1'b0;
        ctrl_memread  = 1'b0;
        ctrl_memwrite = 1'b0;
        ctrl_alusrc   = 1'b0;
        ctrl_branch   = 1'b0;
        ctrl_jump     = 1'b0;
        ctrl_is_jalr  = 1'b0;
        ctrl_alu_op   = ALU_ADD;

        case (opcode)
            7'b0110011: begin // R-type
                ctrl_regwrite = 1'b1;
                case (funct3_id)
                    3'b000: ctrl_alu_op = funct7_id[5] ? ALU_SUB : ALU_ADD;
                    3'b111: ctrl_alu_op = ALU_AND;
                    3'b110: ctrl_alu_op = ALU_OR;
                    3'b100: ctrl_alu_op = ALU_XOR;
                    3'b010: ctrl_alu_op = ALU_SLT;
                    3'b001: ctrl_alu_op = ALU_SLL;
                    3'b101: ctrl_alu_op = ALU_SRL;
                    default: ctrl_alu_op = ALU_ADD;
                endcase
            end
            7'b0010011: begin // I-type ALU
                imm_out       = imm_i;
                ctrl_regwrite = 1'b1;
                ctrl_alusrc   = 1'b1;
                case (funct3_id)
                    3'b000: ctrl_alu_op = ALU_ADD;
                    3'b111: ctrl_alu_op = ALU_AND;
                    3'b110: ctrl_alu_op = ALU_OR;
                    3'b100: ctrl_alu_op = ALU_XOR;
                    3'b010: ctrl_alu_op = ALU_SLT;
                    3'b001: ctrl_alu_op = ALU_SLL;
                    3'b101: ctrl_alu_op = ALU_SRL;
                    default: ctrl_alu_op = ALU_ADD;
                endcase
            end
            7'b0000011: begin // LW
                imm_out       = imm_i;
                ctrl_regwrite = 1'b1;
                ctrl_memread  = 1'b1;
                ctrl_alusrc   = 1'b1;
                ctrl_alu_op   = ALU_ADD;
            end
            7'b0100011: begin // SW
                imm_out       = imm_s;
                ctrl_memwrite = 1'b1;
                ctrl_alusrc   = 1'b1;
                ctrl_alu_op   = ALU_ADD;
            end
            7'b1100011: begin // B-type
                imm_out     = imm_b;
                ctrl_branch = 1'b1;
                ctrl_alusrc = 1'b0;
                ctrl_alu_op = ALU_SUB;
            end
            7'b1101111: begin // JAL
                imm_out       = imm_j;
                ctrl_regwrite = 1'b1;
                ctrl_jump     = 1'b1;
            end
            7'b1100111: begin // JALR
                imm_out       = imm_i;
                ctrl_regwrite = 1'b1;
                ctrl_jump     = 1'b1;
                ctrl_is_jalr  = 1'b1;
                ctrl_alusrc   = 1'b1;
                ctrl_alu_op   = ALU_ADD;
            end
            default: begin
                // NOP / unsupported
            end
        endcase
    end

    // ---------------- Hazard detection (load-use stall) ----------------
    reg stall;
    always @(*) begin
        stall = 1'b0;
        if (idex_memread && (idex_rd != 5'd0) &&
            ((idex_rd == rs1_id) || (idex_rd == rs2_id)))
            stall = 1'b1;
    end

    // ---------------- Forwarding ----------------
    reg [1:0] forward_a;
    reg [1:0] forward_b;

    always @(*) begin
        forward_a = 2'b00;
        if (exmem_regwrite && (exmem_rd != 5'd0) && (exmem_rd == idex_rs1))
            forward_a = 2'b10;
        else if (memwb_regwrite && (memwb_rd != 5'd0) && (memwb_rd == idex_rs1))
            forward_a = 2'b01;
    end

    always @(*) begin
        forward_b = 2'b00;
        if (exmem_regwrite && (exmem_rd != 5'd0) && (exmem_rd == idex_rs2))
            forward_b = 2'b10;
        else if (memwb_regwrite && (memwb_rd != 5'd0) && (memwb_rd == idex_rs2))
            forward_b = 2'b01;
    end

    wire [31:0] memwb_result = memwb_memread ? memwb_mem_data : memwb_alu_result;

    reg [31:0] operand_a;
    reg [31:0] operand_b_reg;

    always @(*) begin
        case (forward_a)
            2'b10:   operand_a = exmem_alu_result;
            2'b01:   operand_a = memwb_result;
            default: operand_a = idex_rs1_data;
        endcase
    end

    always @(*) begin
        case (forward_b)
            2'b10:   operand_b_reg = exmem_alu_result;
            2'b01:   operand_b_reg = memwb_result;
            default: operand_b_reg = idex_rs2_data;
        endcase
    end

    wire [31:0] operand_b = idex_alusrc ? idex_imm : operand_b_reg;

    // ---------------- ALU ----------------
    wire signed [31:0] alu_a = operand_a;
    wire signed [31:0] alu_b = operand_b;
    wire [4:0]         shamt = alu_b[4:0];
    reg  [31:0]        alu_result;

    always @(*) begin
        case (idex_alu_op)
            ALU_ADD: alu_result = alu_a + alu_b;
            ALU_SUB: alu_result = alu_a - alu_b;
            ALU_AND: alu_result = alu_a & alu_b;
            ALU_OR:  alu_result = alu_a | alu_b;
            ALU_XOR: alu_result = alu_a ^ alu_b;
            ALU_SLT: alu_result = (alu_a < alu_b) ? 32'd1 : 32'd0;
            ALU_SLL: alu_result = alu_a << shamt;
            ALU_SRL: alu_result = alu_a >> shamt;
            default: alu_result = 32'd0;
        endcase
    end

    // For jumps, rd = PC + 4
    wire [31:0] ex_result = idex_jump ? (idex_pc + 32'd4) : alu_result;

    // ---------------- Branch evaluation ----------------
    wire signed [31:0] br_a = operand_a;
    wire signed [31:0] br_b = operand_b_reg;
    wire br_eq = (br_a == br_b);
    wire br_lt = (br_a < br_b);

    reg branch_cond;
    always @(*) begin
        branch_cond = 1'b0;
        if (idex_branch) begin
            case (idex_funct3)
                3'b000: branch_cond = br_eq;   // BEQ
                3'b001: branch_cond = ~br_eq;  // BNE
                3'b100: branch_cond = br_lt;   // BLT
                3'b101: branch_cond = ~br_lt;  // BGE
                default: branch_cond = 1'b0;
            endcase
        end
    end

    wire branch_taken = (idex_branch && branch_cond) || idex_jump;

    wire [31:0] branch_target = idex_is_jalr
        ? ((operand_a + idex_imm) & 32'hFFFF_FFFE)
        : (idex_pc + idex_imm);

    // ---------------- PC update ----------------
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            pc <= 32'd0;
        else if (stall)
            pc <= pc;
        else if (branch_taken)
            pc <= branch_target;
        else
            pc <= pc_plus4;
    end

    // ---------------- IF/ID update ----------------
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            ifid_pc   <= 32'd0;
            ifid_inst <= 32'h00000013; // NOP
        end else if (stall) begin
            ifid_pc   <= ifid_pc;
            ifid_inst <= ifid_inst;
        end else if (branch_taken) begin
            ifid_pc   <= 32'd0;
            ifid_inst <= 32'h00000013; // flush -> NOP
        end else begin
            ifid_pc   <= pc;
            ifid_inst <= imem_data;
        end
    end

    // ---------------- ID/EX update ----------------
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            idex_pc       <= 32'd0;
            idex_rs1_data <= 32'd0;
            idex_rs2_data <= 32'd0;
            idex_rs1      <= 5'd0;
            idex_rs2      <= 5'd0;
            idex_rd       <= 5'd0;
            idex_imm      <= 32'd0;
            idex_regwrite <= 1'b0;
            idex_memread  <= 1'b0;
            idex_memwrite <= 1'b0;
            idex_alusrc   <= 1'b0;
            idex_branch   <= 1'b0;
            idex_jump     <= 1'b0;
            idex_is_jalr  <= 1'b0;
            idex_alu_op   <= ALU_ADD;
            idex_funct3   <= 3'b000;
        end else if (stall || branch_taken) begin
            // Insert bubble
            idex_pc       <= 32'd0;
            idex_rs1_data <= 32'd0;
            idex_rs2_data <= 32'd0;
            idex_rs1      <= 5'd0;
            idex_rs2      <= 5'd0;
            idex_rd       <= 5'd0;
            idex_imm      <= 32'd0;
            idex_regwrite <= 1'b0;
            idex_memread  <= 1'b0;
            idex_memwrite <= 1'b0;
            idex_alusrc   <= 1'b0;
            idex_branch   <= 1'b0;
            idex_jump     <= 1'b0;
            idex_is_jalr  <= 1'b0;
            idex_alu_op   <= ALU_ADD;
            idex_funct3   <= 3'b000;
        end else begin
            idex_pc       <= ifid_pc;
            idex_rs1_data <= rs1_data_id;
            idex_rs2_data <= rs2_data_id;
            idex_rs1      <= rs1_id;
            idex_rs2      <= rs2_id;
            idex_rd       <= rd_id;
            idex_imm      <= imm_out;
            idex_regwrite <= ctrl_regwrite;
            idex_memread  <= ctrl_memread;
            idex_memwrite <= ctrl_memwrite;
            idex_alusrc   <= ctrl_alusrc;
            idex_branch   <= ctrl_branch;
            idex_jump     <= ctrl_jump;
            idex_is_jalr  <= ctrl_is_jalr;
            idex_alu_op   <= ctrl_alu_op;
            idex_funct3   <= funct3_id;
        end
    end

    // ---------------- EX/MEM update ----------------
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            exmem_alu_result <= 32'd0;
            exmem_mem_data   <= 32'd0;
            exmem_rd         <= 5'd0;
            exmem_regwrite   <= 1'b0;
            exmem_memread    <= 1'b0;
            exmem_memwrite   <= 1'b0;
        end else begin
            exmem_alu_result <= ex_result;
            exmem_mem_data   <= operand_b_reg;
            exmem_rd         <= idex_rd;
            exmem_regwrite   <= idex_regwrite;
            exmem_memread    <= idex_memread;
            exmem_memwrite   <= idex_memwrite;
        end
    end

    // ---------------- MEM stage ----------------
    assign dmem_addr  = exmem_alu_result;
    assign dmem_wdata = exmem_mem_data;
    assign dmem_wen   = exmem_memwrite;
    assign dmem_be    = 4'b1111;

    // ---------------- MEM/WB update ----------------
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            memwb_mem_data   <= 32'd0;
            memwb_alu_result <= 32'd0;
            memwb_rd         <= 5'd0;
            memwb_regwrite   <= 1'b0;
            memwb_memread    <= 1'b0;
        end else begin
            memwb_mem_data   <= dmem_rdata;
            memwb_alu_result <= exmem_alu_result;
            memwb_rd         <= exmem_rd;
            memwb_regwrite   <= exmem_regwrite;
            memwb_memread    <= exmem_memread;
        end
    end

    // ---------------- WB stage ----------------
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            regfile[0] <= 32'd0;
        end else begin
            regfile[0] <= 32'd0;
            if (memwb_regwrite && (memwb_rd != 5'd0))
                regfile[memwb_rd] <= memwb_result;
        end
    end

endmodule